refentry.refsect1:
  &reftitle.description;

   intarray_unshift
   arrayarray
   mixedvalues


array_unshift ले pass गरिएका elements लाई array को सुरुमा prepend गर्दछ। ध्यान दिनुहोस् कि elements को list लाई एकमुष्ट रूपमा prepend गरिन्छ, ताकि prepend गरिएका elements उही क्रममा रहून्। सबै numerical array keys लाई शून्य from बाट गन्ती सुरु हुने गरी परिमार्जन गरिनेछ, जबकि literal keys परिवर्तन हुने छैनन्।
  &note.reset-index;

&reftitle.changelog;







     &Version;
     &Description;





     7.3.0
     यो function अब केवल एउटा parameter सहित call गर्न सकिन्छ। पहिले, कम्तीमा दुईवटा parameters आवश्यक पर्थ्यो।

  &reftitle.examples;



    array_unshift को उदाहरण


<?php

$queue = [
    "orange",
    "banana"
];

array_unshift($queue, "apple", "raspberry");

var_dump($queue);

?>


    &example.outputs;


array(4) {
  [0]=>
  string(5) "apple"
  [1]=>
  string(9) "raspberry"
  [2]=>
  string(6) "orange"
  [3]=>
  string(6) "banana"
}







    associative arrays सँगको प्रयोग

यदि एउटा associative array लाई अर्को associative array मा prepend गरियो भने, prepend गरिएको array पहिलेको array मा numerically index गरिन्छ।


<?php

$foods = [
    'apples' => [
        'McIntosh' => 'red',
        'Granny Smith' => 'green',
    ],
    'oranges' => [
        'Navel' => 'orange',
        'Valencia' => 'orange',
    ],
];

$vegetables = [
    'lettuce' => [
        'Iceberg' => 'green',
        'Butterhead' => 'green',
    ],
    'carrots' => [
        'Deep Purple Hybrid' => 'purple',
        'Imperator' => 'orange',
    ],
    'cucumber' => [
        'Kirby' => 'green',
        'Gherkin' => 'green',
    ],
];

array_unshift($foods, $vegetables);

var_dump($foods);

?>


    &example.outputs;


array(3) {
  [0]=>
  array(3) {
    ["lettuce"]=>
    array(2) {
      ["Iceberg"]=>
      string(5) "green"
      ["Butterhead"]=>
      string(5) "green"
    }
    ["carrots"]=>
    array(2) {
      ["Deep Purple Hybrid"]=>
      string(6) "purple"
      ["Imperator"]=>
      string(6) "orange"
    }
    ["cucumber"]=>
    array(2) {
      ["Kirby"]=>
      string(5) "green"
      ["Gherkin"]=>
      string(5) "green"
    }
  }
  ["apples"]=>
  array(2) {
    ["McIntosh"]=>
    string(3) "red"
    ["Granny Smith"]=>
    string(5) "green"
  }
  ["oranges"]=>
  array(2) {
    ["Navel"]=>
    string(6) "orange"
    ["Valencia"]=>
    string(6) "orange"
  }
}
